{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Ampicillin, a zwitterionic beta-lactam with a primary amine and carboxylic acid, has an absolute oral bioavailability of 40% in humans, supporting high F for the similarly polar lactam-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Praziquantel, a fused aromatic lactam, has a bioavailability of 27.2% in patients, above the 20% threshold, supporting high for the benzazepine lactam scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Maraviroc, a basic amide with an aromatic ring, has a systemic availability of 22.9% at 100 mg, still above the 20% threshold, indicating that even lower-end F values in this chemical space are high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Diclofenac, a carboxylic acid-containing aromatic drug, has an absolute bioavailability of 54%, supporting high for the acidic aromatic query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar zwitterionic lactam with a primary amine and two carboxylic acids. The closest experimental analogues (ampicillin, praziquantel, maraviroc, diclofenac) all have absolute oral bioavailability above 20%, with ampicillin (40%) being the most transferable due to shared ionizable groups and lactam. Therefore, F >= 20% is supported.",
  "evidence_gaps": [
    "No direct experimental data for the exact benzazepine-lysine scaffold.",
    "Uncertainty about the impact of the second carboxylic acid on permeability.",
    "Lack of healthy-subject data for some analogues (e.g., praziquantel in cirrhotic patients)."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

